<?php
namespace App\Http\Controllers;
use App\Models\Project; use Illuminate\Http\Request; use Inertia\Inertia;
class ProjectController extends Controller { public function index(){ $p=Project::withCount(['tasks','updates'])->latest()->get();return Inertia::render('Projects/Index',['projects'=>$p->map(fn($x)=>['id'=>$x->id,'name'=>$x->name,'description'=>$x->description,'status'=>$x->status,'due_date'=>$x->due_date?->format('Y-m-d'),'tenant'=>$x->tenant?->name,'tasks_count'=>$x->tasks_count,'updates_count'=>$x->updates_count])]); } public function create(){abort_unless(request()->user()->can('create',Project::class),403);return Inertia::render('Projects/Create',['tenants'=>request()->user()->isAdmin()?\App\Models\Tenant::orderBy('name')->get(['id','name']):[]]);} public function store(Request $r){$this->authorize('create',Project::class);$d=$r->validate(['tenant_id'=>request()->user()->isAdmin()?'required|exists:tenants,id':'nullable','name'=>'required|string|max:150','description'=>'nullable|string|max:5000','status'=>'required|in:active,on_hold,completed','due_date'=>'nullable|date']);$p=Project::create($d);return redirect()->route('projects.show',$p)->with('success','Project created.');} public function show(Project $project){$this->authorize('view',$project);$project->load(['tasks','files','updates.user','tenant']);return Inertia::render('Projects/Show',['project'=>['id'=>$project->id,'name'=>$project->name,'description'=>$project->description,'status'=>$project->status,'due_date'=>$project->due_date?->format('Y-m-d'),'tenant'=>$project->tenant?->name,'tasks'=>$project->tasks->map->only(['id','title','status','priority','due_date']),'files'=>$project->files->map->only(['id','name','mime_type','size']),'updates'=>$project->updates->map(fn($u)=>['id'=>$u->id,'body'=>$u->body,'author'=>$u->user?->name,'created_at'=>$u->created_at->toDateTimeString()])]]); } public function update(Request $r,Project $project){$this->authorize('update',$project);$d=$r->validate(['name'=>'required|string|max:150','description'=>'nullable|string|max:5000','status'=>'required|in:active,on_hold,completed','due_date'=>'nullable|date']);$project->update($d);return back()->with('success','Project updated.');} public function destroy(Project $project){$this->authorize('delete',$project);$project->delete();return redirect()->route('projects.index')->with('success','Project deleted.');} }
